"""pwctl → PipeWrench (2026-10-24): the settings folder is copied once; generated files move to the new names
on the next apply, and files the old name made still count as ours."""
import pytest

import pwconfig as pc


@pytest.fixture
def xdg(monkeypatch, tmp_path):
    monkeypatch.setenv("XDG_CONFIG_HOME", str(tmp_path))
    for v in ("PIPEWRENCH_DEVICES", "PIPEWRENCH_PRESETS", "PIPEWRENCH_UI"):
        monkeypatch.delenv(v, raising=False)
    return tmp_path


def test_paths_use_the_new_names(xdg):
    assert pc.config_path() == xdg / "pipewrench" / "devices.json"
    assert pc.dropin_path().name == "50-pipewrench-devices.conf"
    assert pc.labels_path((0, 4, 17)).name == "51-pipewrench-labels.lua"
    assert pc.labels_path((0, 5, 0)).name == "51-pipewrench-labels.conf"
    assert pc.legacy_path(pc.dropin_path()).name == "50-pwctl-devices.conf"
    assert pc.legacy_path(pc.labels_path((0, 4, 17))).name == "51-pwctl-labels.lua"


def test_settings_folder_is_copied_once_and_the_old_one_kept(xdg):
    old = xdg / "pwctl"
    old.mkdir()
    (old / "ui.json").write_text('{"theme": "crowbar"}')
    (old / "devices.json").write_text("{}")
    assert "copied" in pc.migrate_config_dir()
    assert (xdg / "pipewrench" / "ui.json").read_text() == '{"theme": "crowbar"}'
    assert (old / "ui.json").exists()
    (xdg / "pipewrench" / "ui.json").write_text('{"theme": "dark"}')
    assert pc.migrate_config_dir() is None           # never again once the new folder exists
    assert (xdg / "pipewrench" / "ui.json").read_text() == '{"theme": "dark"}'


def test_no_old_folder_no_copy(xdg):
    assert pc.migrate_config_dir() is None
    assert not (xdg / "pipewrench").exists()


def test_old_header_still_counts_as_ours(tmp_path):
    p = tmp_path / "x.conf"
    p.write_text("# Generated by pwctl from devices.json. Do not edit by hand:\n")
    pc.check_ours(p)
    p.write_text("# made by hand\n")
    with pytest.raises(pc.ConfigError):
        pc.check_ours(p)


def test_live_path_is_the_old_file_until_apply(xdg):
    new = pc.dropin_path()
    old = pc.legacy_path(new)
    assert pc.live_path(new) == new                  # neither exists
    old.parent.mkdir(parents=True)
    old.write_text("# Generated by pwctl\n")
    assert pc.live_path(new) == old
    new.write_text("# Generated by PipeWrench\n")
    assert pc.live_path(new) == new


def test_write_retires_the_old_file_and_keeps_it_as_backup(xdg):
    new = pc.dropin_path()
    old = pc.legacy_path(new)
    old.parent.mkdir(parents=True)
    old.write_text("# Generated by pwctl\nold\n")
    old.with_name(old.name + ".bak").write_text("# Generated by pwctl\nolder\n")
    assert pc.write_generated(new, "# Generated by PipeWrench\nnew\n")
    assert new.read_text().endswith("new\n")
    assert new.with_name(new.name + ".bak").read_text().endswith("old\n")   # rollback brings back the old setup
    assert not old.exists()
    assert old.with_name(old.name + ".bak").read_text().endswith("older\n")  # older history kept, inert
    assert pc.rollback_generated(new).startswith("restored")
    assert new.read_text().endswith("old\n")


def test_write_leaves_a_hand_made_old_file_alone(xdg):
    new = pc.dropin_path()
    old = pc.legacy_path(new)
    old.parent.mkdir(parents=True)
    old.write_text("# made by hand\n")
    with pytest.raises(pc.ConfigError):
        pc.write_generated(new, "# Generated by PipeWrench\n")
    assert old.read_text() == "# made by hand\n" and not new.exists()


def test_same_text_under_the_old_name_still_moves(xdg):
    new = pc.dropin_path()
    old = pc.legacy_path(new)
    old.parent.mkdir(parents=True)
    text = "# Generated by PipeWrench\nsame\n"
    old.write_text(text)
    assert pc.write_generated(new, text)
    assert new.read_text() == text and not old.exists()


def test_rendered_files_say_pipewrench():
    c = {**pc.default_config(), "clock_rate": 48000}
    head = pc.render_dropin(c).splitlines()[:2]
    assert "Generated by PipeWrench" in head[0] and "pwrench devices" in head[1]
    assert "pwrench devices label" in pc.render_labels(c, (0, 5, 0))
